const DraftNumberInput: React.FC<{
  value: number;
  min: number;
  max: number;
  step?: string | number;
  fallback: number;
  allowDecimal?: boolean;
  onCommit: (nextVal: number) => void;
  className?: string;
}> = ({
  value,
  min,
  max,
  step = 1,
  fallback,
  allowDecimal = false,
  onCommit,
  className = '',
}) => {
  const [draft, setDraft] = useState(String(value));
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    if (!focused) {
      setDraft(String(value));
    }
  }, [value, focused]);

  const parseDraft = (raw: string): number | null => {
    const cleaned = bnToEnDigits(raw).replace(/,/g, '').trim();
    if (!cleaned || cleaned === '-' || cleaned === '.') return null;
    const n = Number(cleaned);
    if (!Number.isFinite(n)) return null;
    return allowDecimal ? Math.round(n * 100) / 100 : Math.round(n);
  };

  return (
    <input
      type="number"
      step={step}
      min={min}
      max={max}
      value={draft}
      onFocus={() => setFocused(true)}
      onChange={(e) => {
        const raw = e.target.value;
        setDraft(raw);
        const parsed = parseDraft(raw);
        if (parsed !== null && parsed >= min && parsed <= max) {
          onCommit(parsed);
        }
      }}
      onBlur={() => {
        setFocused(false);
        const parsed = parseDraft(draft);
        const finalVal =
          parsed === null ? fallback : Math.max(min, Math.min(max, parsed));
        onCommit(finalVal);
        setDraft(String(finalVal));
      }}
      className={className}
    />
  );
};

