        parsed.push({
          projectNo: parts[0] || `প্রকল্প-${parsed.length + 1}`,
          projectName: parts[1] || '',
          presidentName: parts[2] || '',
          unionName: parts[3] || db.officer.unions[0] || '',
          allocationQty: String(parseNum(parts[4] || '0') || ''),
