                      onMouseDown={(e) => {
                        e.stopPropagation();
                        if (e.button !== 0 || !subPagerRef.current) return;
                        const target = e.target as HTMLElement | null;
                        if (target?.closest('input, select, textarea, button, a, label, table')) {
                          return;
                        }
                        subDragRef.current = {
                          active: true,
                          startX: e.clientX,
                          startScrollLeft: subPagerRef.current.scrollLeft,
                          moved: false,
