  onLock: () => void;
  onUpdateOfficer: (patch: Partial<OfficerProfileSettings>) => void;
  getDCUsage: (
    cat: AllocationCategory,
    dcMemo: string
  ) => { total: number; used: number; remaining: number };
  onSaveUNOBatch: (payload: {
    category: AllocationCategory;
