                    const cnt = allPendingProjects.filter((x) => x.project.category === c).length;
                    return (
                      <button
                        key={c}
                        type="button"
                        onClick={() => setCatFilter(c)}
                        className={`min-h-[36px] shrink-0 whitespace-nowrap rounded-lg px-2.5 py-1 font-bold border cursor-pointer ${
                          catFilter === c
                            ? 'bg-[#E2136E] text-white border-[#E2136E]'
                            : 'bg-white text-slate-700 border-slate-200 hover:bg-rose-50'
                        }`}
                      >
                        {c} ({toBnDigits(cnt)})
                      </button>
                    );
                  })}
                </div>

                {(fiscalYears.length > 0 || availableUnions.length > 0) && (
                  <div className="grid grid-cols-2 gap-2">
                    <select
                      value={fyFilter}
                      onChange={(e) => setFyFilter(e.target.value)}
                      className="min-h-[38px] rounded-xl border border-slate-300 bg-white px-2.5 py-1 text-xs font-semibold"
                    >
                      <option value="ALL">সকল সাল / অর্থবছর</option>
                      {fiscalYears.map((fy) => (
                        <option key={fy} value={fy}>
                          {fy}
                        </option>
                      ))}
                    </select>
                    <select
                      value={unionFilter}
                      onChange={(e) => setUnionFilter(e.target.value)}
                      className="min-h-[38px] rounded-xl border border-slate-300 bg-white px-2.5 py-1 text-xs font-semibold"
                    >
                      <option value="ALL">সকল ইউনিয়ন</option>
                      {availableUnions.map((u) => (
                        <option key={u} value={u}>
                          {u}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>

              {filteredPendingProjects.length === 0 ? (
                <div className="rounded-2xl border border-dashed border-slate-300 bg-white py-10 px-4 text-center space-y-2 text-xs text-slate-500">
                  <p>কোনো পেন্ডিং প্রকল্প পাওয়া যায়নি।</p>
                  {onOpenDCStage && (
                    <button
                      type="button"
                      onClick={() =>
                        onOpenDCStage(catFilter === 'ALL' ? 'জি আর' : catFilter)
                      }
                      className="min-h-[40px] inline-flex items-center gap-1.5 rounded-xl border border-rose-300 bg-rose-50 px-4 py-2 font-bold text-[#E2136E] cursor-pointer"
                    >
                      <span>ডিসি ধাপে নতুন প্রকল্প যোগ করুন</span>
                    </button>
                  )}
                </div>
              ) : (
                <div className="space-y-2.5">
                  <div className="text-[11px] font-semibold text-slate-500 px-1">
                    প্রকল্পে টাচ করে এন্ট্রি ও সেভ করুন, অথবা বামে স্লাইড করে অন্য স্মারকে/খাতে স্থানান্তর করুন
                  </div>
                  {filteredPendingProjects.map(renderProjectCard)}
                </div>
              )}
            </div>

            {/* SLIDE 2: DC ALLOCATION GROUPED VIEW (জেলা প্রশাসক / ডিসি স্মারকসমূহ) */}
            <div className="w-full shrink-0 snap-center snap-always space-y-3">
              <div className="rounded-2xl border border-slate-200 bg-white p-3 space-y-2 text-xs">
                <div className="font-bold text-slate-800">
                  জেলা প্রশাসক (ডিসি) স্মারক নির্বাচন করুন
                </div>
                <select
                  value={selectedDcKey}
                  onChange={(e) => setSelectedDcKey(e.target.value)}
                  className="w-full min-h-[42px] rounded-xl border border-slate-300 bg-white px-3 py-2 text-xs font-semibold"
                >
                  <option value="ALL">
                    সকল ডিসি স্মারকের পেন্ডিং প্রকল্প ({toBnDigits(allPendingProjects.length)}টি)
                  </option>
                  {dcMemoGroups.map((g) => (
                    <option key={g.key} value={g.key}>
                      {g.category} · ডিসি: {toBnDigits(g.dcMemo)} ({formatBnDate(g.dcDate)}) —{' '}
                      {toBnDigits(g.items.length)}টি পেন্ডিং ({formatBnQty(g.remaining)} মে.টন বাকি)
                    </option>
                  ))}
                </select>
              </div>

              {dcFilteredPendingProjects.length === 0 ? (
                <div className="rounded-2xl border border-dashed border-slate-300 bg-white py-10 px-4 text-center text-xs text-slate-500">
                  নির্বাচিত ডিসি স্মারকে কোনো পেন্ডিং প্রকল্প নেই।
                </div>
              ) : (
                <div className="space-y-2.5">
                  {dcFilteredPendingProjects.map(renderProjectCard)}
                </div>
              )}
            </div>

            {/* SLIDE 3: SAVED UNO PROJECT ALLOCATIONS (বরাদ্দকৃত তালিকা) */}
            <div className="w-full shrink-0 snap-center snap-always">
              <div className="rounded-2xl border border-slate-200 bg-white overflow-hidden">
                <div className="px-3.5 py-2.5 border-b border-slate-200 bg-slate-50/70 text-xs font-bold text-slate-900">
                  জি আর ও কাবিখা বরাদ্দকৃত প্রকল্প তালিকা ({formatBnInt(projectCategoryUnoSubs.length)}টি)
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-xs border-collapse tabular-nums">
                    <thead>
                      <tr className="bg-slate-50 border-b border-slate-200 text-slate-700 font-bold">
                        <th className="py-2 px-2.5 text-left">খাত ও স্মারক</th>
                        <th className="py-2 px-2.5 text-left">প্রকল্প / সভাপতি</th>
                        <th className="py-2 px-2.5 text-right">বরাদ্দ (মে.টন)</th>
                        <th className="py-2 px-2.5 text-center">কাজ</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {projectCategoryUnoSubs.length === 0 ? (
                        <tr>
                          <td colSpan={4} className="py-8 text-center text-slate-500">
                            এখনো কোনো প্রকল্পের ইউএনও উপবরাদ্দ সেভ করা হয়নি।
                          </td>
                        </tr>
                      ) : (
                        projectCategoryUnoSubs.map((u) => {
                          const isEditing = editingSubRow?.id === u.id;
                          return (
                            <tr key={u.id} className={isEditing ? 'bg-rose-50/50' : ''}>
                              <td className="py-2 px-2.5">
                                <div className="font-bold text-[#E2136E]">{u.category}</div>
                                {isEditing ? (
                                  <div className="space-y-1 mt-1">
                                    <input
                                      type="text"
                                      value={editingSubRow.unoMemo}
                                      onChange={(e) =>
                                        setEditingSubRow((prev) =>
                                          prev ? { ...prev, unoMemo: e.target.value } : prev
                                        )
                                      }
                                      className="w-full rounded border border-slate-300 px-2 py-1 text-xs"
                                    />
                                    <input
                                      type="date"
                                      value={editingSubRow.unoDate}
                                      onChange={(e) =>
                                        setEditingSubRow((prev) =>
                                          prev ? { ...prev, unoDate: e.target.value } : prev
                                        )
                                      }
                                      className="w-full rounded border border-slate-300 px-2 py-1 text-xs"
                                    />
                                  </div>
                                ) : (
                                  <div className="text-[11px] text-slate-600">
                                    ইউএনও: {toBnDigits(u.unoMemo)} ({formatBnDate(u.unoDate)})
                                  </div>
                                )}
                              </td>
                              <td className="py-2 px-2.5">
                                {isEditing ? (
                                  <div className="space-y-1">
                                    <input
                                      type="text"
                                      value={editingSubRow.recipient}
                                      onChange={(e) =>
                                        setEditingSubRow((prev) =>
                                          prev ? { ...prev, recipient: e.target.value } : prev
                                        )
                                      }
                                      className="w-full rounded border border-slate-300 px-2 py-1 text-xs"
                                    />
                                  </div>
                                ) : (
                                  <>
                                    <div className="font-semibold text-slate-900">
                                      {u.recipientName} · {u.unionName}
                                    </div>
                                    <div className="text-[11px] text-slate-500">
                                      {u.projectNo ? `প্রকল্প ${toBnDigits(u.projectNo)}` : ''}
                                      {u.projectName ? ` — ${u.projectName}` : ''}
                                    </div>
                                  </>
                                )}
                              </td>
                              <td className="py-2 px-2.5 text-right font-bold">
                                {isEditing ? (
                                  <input
                                    type="number"
                                    step="0.001"
                                    value={editingSubRow.qty}
                                    onChange={(e) =>
                                      setEditingSubRow((prev) =>
                                        prev ? { ...prev, qty: e.target.value } : prev
                                      )
                                    }
                                    className="w-24 rounded border border-slate-300 px-2 py-1 text-right font-bold"
                                  />
                                ) : (
                                  formatBnQty(u.allocationQty)
                                )}
                              </td>
                              <td className="py-2 px-2.5 text-center whitespace-nowrap">
                                {isEditing ? (
                                  <div className="inline-flex items-center gap-1">
                                    <button
                                      type="button"
                                      onClick={() => {
                                        if (!onUpdateUNOSub) return;
                                        const res = onUpdateUNOSub(u.id, {
                                          unoMemo: editingSubRow.unoMemo,
                                          unoDate: editingSubRow.unoDate,
                                          recipientName: editingSubRow.recipient,
                                          unionName: editingSubRow.unionName,
                                          allocationQty: parseNum(editingSubRow.qty),
                                        });
                                        setFeedback({
                                          ok: res.ok,
                                          text: res.ok
                                            ? res.message || 'হালনাগাদ হয়েছে।'
                                            : res.error || 'হালনাগাদ হয়নি।',
                                        });
                                        if (res.ok) setEditingSubRow(null);
                                      }}
                                      className="p-2 text-white bg-[#E2136E] hover:bg-[#B80D58] rounded cursor-pointer"
                                    >
                                      <Check className="h-3.5 w-3.5" />
                                    </button>
                                    <button
                                      type="button"
                                      onClick={() => setEditingSubRow(null)}
                                      className="p-2 text-slate-600 bg-slate-100 rounded cursor-pointer"
                                    >
                                      <X className="h-3.5 w-3.5" />
                                    </button>
                                  </div>
                                ) : (
                                  <div className="inline-flex items-center gap-1">
                                    {onUpdateUNOSub && (
                                      <button
                                        type="button"
                                        onClick={() =>
                                          setEditingSubRow({
                                            id: u.id,
                                            unoMemo: u.unoMemo,
                                            unoDate: u.unoDate,
                                            recipient: u.recipientName,
                                            unionName: u.unionName,
                                            qty: String(u.allocationQty),
                                          })
                                        }
                                        className="p-2 text-[#E2136E] hover:bg-rose-50 rounded cursor-pointer"
                                      >
                                        <Pencil className="h-3.5 w-3.5" />
                                      </button>
                                    )}
                                    <button
                                      type="button"
                                      onClick={() => onDeleteUNOSub(u.id)}
                                      className="p-2 text-rose-600 hover:bg-rose-50 rounded cursor-pointer"
                                    >
                                      <Trash2 className="h-3.5 w-3.5" />
                                    </button>
                                  </div>
                                )}
                              </td>
                            </tr>
                          );
                        })
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowLeft,
  BookOpen,
  Download,
  Edit3,
  Filter,
  Flame,
  Hammer,
  HeartHandshake,
  Printer,
  Receipt,
  RectangleHorizontal,
  RotateCcw,
  Search,
  ShoppingBag,
  Smartphone,
  Users,
  Wheat,
} from 'lucide-react';
import {
  REPORT_TEMPLATE_CATALOG,
  type AllocationDatabase,
  type RegisterId,
  type ReportTemplateId,
} from '../types/allocation';
import { buildRegisterData } from '../shared/allocReportEngine';
import { formatBnInt } from '../shared/bnUtils';
import {
  OfficialA4Document,
  type OfficialA4DocumentHandle,
} from './OfficialA4Document';

interface RegistersViewProps {
  db: AllocationDatabase;
  activeRegisterId: RegisterId;
  openTrigger?: number;
  onSelectRegister: (regId: RegisterId) => void;
  onEditTemplate: (tplId: ReportTemplateId) => void;
  onChangeOrientation: (tplId: ReportTemplateId, orientation: 'portrait' | 'landscape') => void;
}

const REGISTER_ICON_META: Record<
  RegisterId,
  { icon: React.ComponentType<{ className?: string }>; bg: string; fg: string }
> = {
  'reg-food': { icon: Wheat, bg: 'bg-rose-50 border-rose-200', fg: 'text-[#E2136E]' },
  'reg-oms-gen': { icon: ShoppingBag, bg: 'bg-sky-50 border-sky-200', fg: 'text-sky-700' },
  'reg-oms-spc': { icon: ShoppingBag, bg: 'bg-indigo-50 border-indigo-200', fg: 'text-indigo-700' },
  'reg-oms-tcb': { icon: ShoppingBag, bg: 'bg-violet-50 border-violet-200', fg: 'text-violet-700' },
  'reg-ep-rice': { icon: Flame, bg: 'bg-amber-50 border-amber-200', fg: 'text-amber-700' },
  'reg-ep-wheat': { icon: Flame, bg: 'bg-orange-50 border-orange-200', fg: 'text-orange-700' },
  'reg-vgf-fish': { icon: HeartHandshake, bg: 'bg-cyan-50 border-cyan-200', fg: 'text-cyan-700' },
  'reg-vgf-eid': { icon: HeartHandshake, bg: 'bg-teal-50 border-teal-200', fg: 'text-teal-700' },
  'reg-gr': { icon: HeartHandshake, bg: 'bg-rose-50 border-rose-200', fg: 'text-rose-700' },
  'reg-kab-gen-rice': { icon: Hammer, bg: 'bg-lime-50 border-lime-200', fg: 'text-lime-700' },
  'reg-kab-gen-wheat': { icon: Hammer, bg: 'bg-yellow-50 border-yellow-200', fg: 'text-yellow-700' },
  'reg-kab-spc-rice': { icon: Hammer, bg: 'bg-emerald-50 border-emerald-200', fg: 'text-emerald-700' },
  'reg-kab-spc-wheat': { icon: Hammer, bg: 'bg-amber-50 border-amber-200', fg: 'text-amber-800' },
  'reg-vwb': { icon: Users, bg: 'bg-purple-50 border-purple-200', fg: 'text-purple-700' },
  'reg-kernel': { icon: Wheat, bg: 'bg-emerald-50 border-emerald-200', fg: 'text-emerald-700' },
  'reg-challan': { icon: Receipt, bg: 'bg-slate-100 border-slate-300', fg: 'text-slate-700' },
};

export const RegistersView: React.FC<RegistersViewProps> = ({
  db,
  activeRegisterId,
  openTrigger = 0,
  onSelectRegister,
  onEditTemplate,
  onChangeOrientation,
}) => {
  const docRef = useRef<OfficialA4DocumentHandle>(null);
  const [showIconGrid, setShowIconGrid] = useState<boolean>(openTrigger === 0);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [challanFilter, setChallanFilter] = useState<'ALL' | 'excess' | 'deficit'>('ALL');
  const [showFooterSig, setShowFooterSig] = useState(false);

  useEffect(() => {
    if (openTrigger > 0) {
      setShowIconGrid(false);
    }
  }, [openTrigger]);

  const registerItems = useMemo(
    () => REPORT_TEMPLATE_CATALOG.filter((item) => item.kind === 'register'),
    []
  );

  const template = db.templates[activeRegisterId];

  const built = useMemo(
    () => buildRegisterData(activeRegisterId, db, startDate, endDate, template),
    [activeRegisterId, db, startDate, endDate, template]
  );

  const filteredRows = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return built.rows.filter((r) => {
      if (activeRegisterId === 'reg-challan' && challanFilter !== 'ALL') {
        if (challanFilter === 'excess' && !r.hasSignature) return false;
        if (challanFilter === 'deficit' && r.highlight !== 'deficit') return false;
      }
      if (!q) return true;
      return Object.values(r.cells).some((val) =>
        String(val || '').toLowerCase().includes(q)
      );
    });
  }, [built.rows, searchQuery, activeRegisterId, challanFilter]);

  const signedCount = useMemo(
    () => filteredRows.filter((r) => r.hasSignature).length,
    [filteredRows]
  );

  const isChallan = activeRegisterId === 'reg-challan';
  const currentOrientation = template?.orientation || 'landscape';

  if (showIconGrid) {
    return (
      <div className="space-y-4 font-nikosh">
        <div className="space-y-3">
          <div className="flex items-center justify-between gap-2">
            <div>
              <h2 className="text-base font-bold text-slate-900">সকল রেজিস্টার খাতা</h2>
              <p className="text-xs text-slate-500">
                যেকোনো আইকনে ট্যাপ করলে সংশ্লিষ্ট রেজিস্টার পেজটি সরাসরি ওপেন হবে।
              </p>
            </div>
            <span className="text-[11px] font-bold text-[#E2136E] tabular-nums shrink-0">
              {formatBnInt(registerItems.length)}টি খাত
            </span>
          </div>

          <div className="grid grid-cols-4 sm:grid-cols-5 lg:grid-cols-7 gap-y-4 gap-x-2 pt-1">
            {registerItems.map((item) => {
              const id = item.id as RegisterId;
              const style = REGISTER_ICON_META[id] || {
                icon: BookOpen,
                bg: 'bg-rose-50 border-rose-200',
                fg: 'text-[#E2136E]',
              };
              const Icon = style.icon;
              return (
                <button
                  key={id}
                  type="button"
                  onClick={() => {
                    onSelectRegister(id);
                    setShowIconGrid(false);
                  }}
                  className="group flex flex-col items-center text-center gap-1.5 p-1 rounded-2xl hover:bg-rose-50/60 transition-colors cursor-pointer min-h-[84px]"
                >
                  <span
                    className={`h-14 w-14 rounded-full border flex items-center justify-center shadow-xs group-hover:scale-105 transition-transform ${style.bg} ${style.fg}`}
                  >
                    <Icon className="h-6 w-6" />
                  </span>
                  <span className="text-[11px] sm:text-xs font-bold leading-tight text-slate-800 line-clamp-2">
                    {item.label}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3 font-nikosh">
      {/* Opened Register Compact Header & Symbol-Only Action Controls */}
      <div className="no-print rounded-2xl border border-slate-200 bg-white p-3.5 space-y-3">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setShowIconGrid(true)}
              className="min-h-[40px] inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-slate-50 hover:bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-800 cursor-pointer"
            >
              <ArrowLeft className="h-4 w-4 text-[#E2136E]" />
              <span>সকল রেজিস্টার</span>
            </button>
            <h2 className="text-sm sm:text-base font-bold text-slate-900">
              {template.reportTitle || template.label}
            </h2>
          </div>

          <div className="text-[11px] font-bold text-slate-700 bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-1.5 tabular-nums">
            সারি: {formatBnInt(filteredRows.length)} · স্বাক্ষরযুক্ত: {formatBnInt(signedCount)}
          </div>
        </div>

        {/* Date From (Left), Date To (Right) */}
        <div className="grid grid-cols-2 items-end gap-2.5 pt-2 border-t border-slate-100 text-xs">
          <div>
            <label className="block text-[11px] font-bold text-slate-600 mb-1">শুরু তারিখ</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="w-full min-h-[42px] rounded-xl border border-slate-300 px-2.5 py-1.5 bg-white"
            />
          </div>

          <div>
            <label className="block text-[11px] font-bold text-slate-600 mb-1">শেষ তারিখ</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="w-full min-h-[42px] rounded-xl border border-slate-300 px-2.5 py-1.5 bg-white"
            />
          </div>
        </div>

        {/* Search, Challan Mismatch Filter & Footer Signature Toggle */}
        <div className="flex flex-wrap items-center gap-2.5 pt-2 border-t border-slate-100 text-xs">
          <div className="relative flex-1 min-w-[180px]">
            <Search className="h-3.5 w-3.5 text-slate-400 absolute left-2.5 top-3" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ডিলার, স্মারক, ডিও বা প্রকল্প..."
              className="w-full min-h-[38px] rounded-xl border border-slate-300 pl-8 pr-2.5 py-1.5"
            />
          </div>

          {isChallan && (
            <div className="inline-flex items-center gap-1.5">
              <Filter className="h-3.5 w-3.5 text-slate-500" />
              <select
                value={challanFilter}
                onChange={(e) => setChallanFilter(e.target.value as 'ALL' | 'excess' | 'deficit')}
                className="min-h-[38px] rounded-xl border border-slate-300 px-2.5 py-1.5 bg-white font-bold"
              >
                <option value="ALL">সকল চালান</option>
                <option value="excess">সঠিক / বেশি জমা (স্বাক্ষরযুক্ত)</option>
                <option value="deficit">কম জমা (গরমিল)</option>
              </select>
            </div>
          )}

          {(startDate || endDate || searchQuery || challanFilter !== 'ALL') && (
            <button
