function makeUniqueId(rawId: string, prefix: string, index: number, seenIds: Set<string>): string {
  const base = rawId.trim() || `${prefix}-${index}`;
  if (!seenIds.has(base)) {
    seenIds.add(base);
    return base;
  }
  let suffix = 1;
  while (seenIds.has(`${base}-${suffix}`)) suffix++;
  const unique = `${base}-${suffix}`;
  seenIds.add(unique);
  return unique;
}

