export async function fetchAllocationFromAppsScript(
  rawAppsScriptUrl: string,
  rawSpreadsheetId: string,
  currentDb?: AllocationDatabase
): Promise<{
  db: AllocationDatabase;
  title: string;
  spreadsheetId: string;
  tabsFound: string[];
  matchedTabNames: string[];
}> {
  const cleanUrl = rawAppsScriptUrl.trim();
  if (!cleanUrl || (!cleanUrl.startsWith('https://') && !cleanUrl.startsWith('http://'))) {
    throw new Error('সঠিক Apps Script Web App URL (https://script.google.com/...) দিন।');
  }
  const spreadsheetId = extractSpreadsheetId(rawSpreadsheetId);
  const res = await callGasAction<{
    title?: string;
    spreadsheetId?: string;
    sheetTitles?: string[];
    tables?: Record<string, unknown[][]>;
  }>(cleanUrl, 'readAllTabs', { spreadsheetId });

  if (!res.ok || !res.data?.tables) {
    throw new Error(
      res.error ||
        'Apps Script থেকে শিট পড়া যায়নি। Code.gs-এ নতুন আপডেট করা কোড বসিয়ে Version: New version দিয়ে Deploy করুন।'
    );
  }

  const tablesMap = res.data.tables || {};
  const sheetTitles = Array.isArray(res.data.sheetTitles)
    ? res.data.sheetTitles
    : Object.keys(tablesMap);
  const sheetTitle = String(res.data.title || 'Google Sheet');
  const resolvedSpreadsheetId = String(res.data.spreadsheetId || spreadsheetId || '');

  const entries: Array<[AllocationRawTabKey, { name: string; aliases: readonly string[] }]> = [
    ...(Object.entries(ALLOC_SHEET_TABS) as Array<
      [keyof typeof ALLOC_SHEET_TABS, (typeof ALLOC_SHEET_TABS)[keyof typeof ALLOC_SHEET_TABS]]
    >),
    ['legacyProjects', LEGACY_COMBINED_PROJECTS_TAB],
  ];

  const rawTables: Partial<Record<AllocationRawTabKey, unknown[][]>> = {};
  const matchedTabs = new Set<AllocationRawTabKey>();
  const matchedTabNames: string[] = [];

  for (const [key, def] of entries) {
    const candidates = findAllMatchingSheetTitlesForWrite(
      sheetTitles,
      def.name,
      def.aliases,
      !isExactOnlyTabKey(key),
      key
    );
    if (candidates.length === 0) continue;

    let chosenName = candidates[0];
    let chosenRows = Array.isArray(tablesMap[chosenName]) ? tablesMap[chosenName] : [];
    if (chosenRows.length <= 1 && candidates.length > 1) {
      for (const altName of candidates.slice(1)) {
        const altRows = Array.isArray(tablesMap[altName]) ? tablesMap[altName] : [];
        if (altRows.length > 1) {
          chosenName = altName;
          chosenRows = altRows;
          break;
        }
      }
    }
    matchedTabs.add(key);
    matchedTabNames.push(chosenName);
    rawTables[key] = chosenRows;
  }

  if (matchedTabs.size === 0 && sheetTitles.length > 0) {
    throw new Error(
      `"${sheetTitle}" শিটে বরাদ্দ/ডিও-এর কাঙ্ক্ষিত ট্যাব পাওয়া যায়নি (পাওয়া ট্যাব: ${sheetTitles.slice(0, 6).join(', ')}).`
    );
  }

  return {
    db: buildAllocationDbFromRawTables(rawTables, matchedTabs, currentDb),
    title: sheetTitle,
    spreadsheetId: resolvedSpreadsheetId,
    tabsFound: sheetTitles,
    matchedTabNames,
  };
}

function stableChallanHash(seed: string): string {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

function makeDeterministicChallanId(
  prefix: string,
  challanType: ChallanRecord['challanType'],
  challanNo: string,
  challanDate: string,
  dealerName: string,
  category: string,
  rowIndex: number,
  seenIds: Set<string>
): string {
  const nNo = normChallanNo(challanNo);
  const seed = nNo
    ? `${challanType}|${nNo}`
    : `${challanType}|${toIsoDateStr(challanDate)}|${normPersonName(dealerName)}|${category}|${rowIndex}`;
  let candidate = `${prefix}-${stableChallanHash(seed)}`;
  if (!seenIds.has(candidate)) {
    seenIds.add(candidate);
    return candidate;
  }
  let suffix = 1;
  while (seenIds.has(`${candidate}-${suffix}`)) suffix++;
  candidate = `${candidate}-${suffix}`;
  seenIds.add(candidate);
  return candidate;
}

export function deduplicateChallanRecords(challans: ChallanRecord[]): ChallanRecord[] {
  const dedupMap = new Map<string, ChallanRecord>();
  const exactRowSeen = new Map<string, string>();

  const shouldPreferNew = (existing: ChallanRecord, candidate: ChallanRecord): boolean => {
    const existingIso = toIsoDateStr(existing.challanDate) || '9999-99-99';
    const newIso = toIsoDateStr(candidate.challanDate) || '9999-99-99';
    if (newIso !== existingIso) return newIso < existingIso;
    if ((candidate.recordedAmount > 0) !== (existing.recordedAmount > 0)) {
      return candidate.recordedAmount > 0;
    }
    if (Boolean(candidate.allocationQty) !== Boolean(existing.allocationQty)) {
      return Boolean(candidate.allocationQty);
    }
    if (Boolean(candidate.dealerAllocationId) !== Boolean(existing.dealerAllocationId)) {
      return Boolean(candidate.dealerAllocationId);
    }
    if (Boolean(candidate.sourceRowId) !== Boolean(existing.sourceRowId)) {
      return Boolean(candidate.sourceRowId);
    }
    if (candidate.depositedAmount !== existing.depositedAmount) {
      return candidate.depositedAmount > existing.depositedAmount;
    }
    const candNo = String(candidate.challanNo || '').trim();
    const exNo = String(existing.challanNo || '').trim();
    if (candNo.length !== exNo.length) {
      return candNo.length > exNo.length;
    }
    return false;
  };

  const mergeMeta = (winner: ChallanRecord, loser: ChallanRecord): ChallanRecord => {
    const winnerNo = String(winner.challanNo || '').trim();
    const loserNo = String(loser.challanNo || '').trim();
    const preservedNo =
      loserNo.length > winnerNo.length && normChallanNo(loserNo) === normChallanNo(winnerNo)
        ? loserNo
        : winner.challanNo;
    return {
      ...winner,
      sourceRowId: winner.sourceRowId || loser.sourceRowId,
      challanNo: preservedNo,
      challanDate: winner.challanDate || loser.challanDate,
      dealerName: winner.dealerName && winner.dealerName !== '—' ? winner.dealerName : loser.dealerName,
      bankName: winner.bankName || loser.bankName,
      doNo: winner.doNo || loser.doNo,
      doDate: winner.doDate || loser.doDate,
      dealerAllocationId: winner.dealerAllocationId || loser.dealerAllocationId,
      allocationQty: winner.allocationQty || loser.allocationQty,
      recordedAmount: winner.recordedAmount > 0 ? winner.recordedAmount : loser.recordedAmount,
      depositedAmount: winner.depositedAmount > 0 ? winner.depositedAmount : loser.depositedAmount,
      note: winner.note || loser.note,
    };
  };

  for (const c of challans) {
    const nNo = normChallanNo(c.challanNo);
    let dedupKey = nNo ? `${nNo}::${c.challanType}` : `id::${c.id}`;

    if (nNo && c.depositedAmount > 0) {
      const exactKey = `${nNo}::${toIsoDateStr(c.challanDate)}::${round2(c.depositedAmount)}::${normPersonName(c.dealerName)}::${c.category}`;
      const priorKey = exactRowSeen.get(exactKey);
      if (priorKey && priorKey !== dedupKey) {
        dedupKey = priorKey;
      } else {
        exactRowSeen.set(exactKey, dedupKey);
      }
    }

    const existing = dedupMap.get(dedupKey);
    if (!existing) {
      dedupMap.set(dedupKey, c);
    } else if (shouldPreferNew(existing, c)) {
      dedupMap.set(dedupKey, mergeMeta(c, existing));
    } else {
      dedupMap.set(dedupKey, mergeMeta(existing, c));
    }
  }

  return Array.from(dedupMap.values());
}

export function sortChallansCleanly(challans: ChallanRecord[]): ChallanRecord[] {
  return [...challans].sort((a, b) => {
    const da = toIsoDateStr(a.challanDate) || '9999-99-99';
    const dbDate = toIsoDateStr(b.challanDate) || '9999-99-99';
    if (da !== dbDate) return da.localeCompare(dbDate);
    if (a.category !== b.category) return a.category.localeCompare(b.category, 'bn');
    const na = bnToEnDigits(a.challanNo || '');
    const nb = bnToEnDigits(b.challanNo || '');
    const noCmp = na.localeCompare(nb, undefined, { numeric: true });
    if (noCmp !== 0) return noCmp;
    if (a.challanType !== b.challanType) {
      return a.challanType === 'মূল চালান' ? -1 : 1;
    }
    return (a.dealerName || '').localeCompare(b.dealerName || '', 'bn');
  });
}

export function recoverMissingChallansFromDOs(db: AllocationDatabase): {
  db: AllocationDatabase;
  recoveredCount: number;
  duplicatesRemoved: number;
} {
  const beforeLen = db.challans.length;
  const deduped = deduplicateChallanRecords(db.challans);
  const duplicatesRemoved = Math.max(0, beforeLen - deduped.length);

  const existingKeys = new Set<string>();
  for (const c of deduped) {
    const nNo = normChallanNo(c.challanNo);
    if (nNo) existingKeys.add(`${nNo}::${c.challanType}`);
  }

  const rateMap = new Map(db.rates.map((r) => [r.category, r]));
  const recovered: ChallanRecord[] = [];
  const seenIds = new Set(deduped.map((c) => c.id));

  db.doIssues.forEach((d, idx) => {
    const rateRec = rateMap.get(d.category);
    const unitPrice = rateRec?.unitPrice || (d.category === 'খাদ্য বান্ধব' ? 13000 : 0);
    const taxRate = rateRec?.taxRate || (d.category === 'খাদ্য বান্ধব' ? 200 : 0);

    const mainNo = String(d.challanNo || '').trim();
    const mainNorm = normChallanNo(mainNo);
    if (mainNorm && !existingKeys.has(`${mainNorm}::মূল চালান`)) {
      existingKeys.add(`${mainNorm}::মূল চালান`);
      const cDate = d.challanDate || d.issueDate || '';
      const recAmt =
        d.requiredAmount && d.requiredAmount > 0
          ? d.requiredAmount
          : round2((d.allocationQty || 0) * unitPrice);
      const depAmt = d.challanAmount && d.challanAmount > 0 ? d.challanAmount : recAmt;
      recovered.push({
        id: makeDeterministicChallanId(
          'ch-rec-m',
          'মূল চালান',
          mainNo,
          cDate,
          d.recipientName,
          d.category,
          idx,
          seenIds
        ),
        challanNo: mainNo,
        challanDate: cDate,
        category: d.category,
        dealerName: d.recipientName,
        dealerAllocationId: d.dealerAllocationId,
        challanType: 'মূল চালান',
        bankName: '',
        doNo: d.doNo,
        doDate: d.issueDate,
        allocationQty: d.allocationQty > 0 ? round3(d.allocationQty) : undefined,
        recordedAmount: round2(recAmt),
        depositedAmount: round2(depAmt),
        note: 'ডিও রেকর্ড থেকে পুনরুদ্ধার',
        createdAt: d.createdAt || (cDate ? `${cDate}T00:00:00.000Z` : '2025-01-01T00:00:00.000Z'),
      });
    }

    const taxNo = String(d.taxChallanNo || '').trim();
    const taxNorm = normChallanNo(taxNo);
    if (taxNorm && !existingKeys.has(`${taxNorm}::আয়কর চালান`)) {
      existingKeys.add(`${taxNorm}::আয়কর চালান`);
      const tDate = d.taxChallanDate || d.challanDate || d.issueDate || '';
      const recTax =
        d.requiredTaxAmount && d.requiredTaxAmount > 0
          ? d.requiredTaxAmount
          : round2((d.allocationQty || 0) * taxRate);
      const depTax = d.taxChallanAmount && d.taxChallanAmount > 0 ? d.taxChallanAmount : recTax;
      recovered.push({
        id: makeDeterministicChallanId(
          'ch-rec-t',
          'আয়কর চালান',
          taxNo,
          tDate,
          d.recipientName,
          d.category,
          idx,
          seenIds
        ),
        challanNo: taxNo,
        challanDate: tDate,
        category: d.category,
        dealerName: d.recipientName,
        dealerAllocationId: d.dealerAllocationId,
        challanType: 'আয়কর চালান',
        bankName: '',
        doNo: d.doNo,
        doDate: d.issueDate,
        allocationQty: d.allocationQty > 0 ? round3(d.allocationQty) : undefined,
        recordedAmount: round2(recTax),
        depositedAmount: round2(depTax),
        note: 'ডিও রেকর্ড থেকে পুনরুদ্ধার',
        createdAt: d.createdAt || (tDate ? `${tDate}T00:00:00.000Z` : '2025-01-01T00:00:00.000Z'),
      });
    }
  });

  const merged = sortChallansCleanly(deduplicateChallanRecords([...deduped, ...recovered]));
  const nextDb = reconcileChallansAndDOs({
    ...db,
    challans: merged,
  });

  return {
    db: nextDb,
    recoveredCount: recovered.length,
    duplicatesRemoved,
  };
}

function splitDelimitedLine(line: string, preferTab: boolean): string[] {
  if (preferTab) {
    return line.split('\t').map((c) => c.trim());
  }
  const out: string[] = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === ',' && !inQuotes) {
      out.push(cur.trim());
      cur = '';
    } else {
      cur += ch;
    }
  }
  out.push(cur.trim());
  return out;
}

export function parsePastedChallanTableText(rawText: string): ChallanRecord[] {
  const clean = String(rawText || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const lines = clean
    .split('\n')
    .map((l) => l.trimEnd())
    .filter((l) => l.trim().length > 0);
  if (lines.length === 0) return [];

  const preferTab = lines.some((l) => l.includes('\t'));
  const grid = lines.map((l) => splitDelimitedLine(l, preferTab));

  const firstRowTokens = (grid[0] || []).map((cell) => normColKey(cell));
  const challanHeaderHintTokens = [
    'challanno', 'mainchallanno', 'taxchallanno', 'challandate', 'dealername', 'dealer',
    'category', 'challantype', 'depositedamount', 'recordedamount', 'dono', 'bankname',
    'চালাননং', 'চালাননম্বর', 'চালানেরতারিখ', 'ডিলারেরনাম', 'ডিলার', 'খাত', 'জমাকৃতটাকা', 'ব্যাংক',
  ];
  const looksLikeHeader = firstRowTokens.some((tok) =>
    challanHeaderHintTokens.some((h) => tok === h || tok.includes(h))
  );

  if (looksLikeHeader) {
    return parseChallanRowsFromTable(grid);
  }

  // No header pasted (e.g., raw rows copied from Google Sheet Version History):
  // Default Challan tab column order: challanNo, challanDate, category, dealerName, challanType, bankName, doNo, recordedAmount, depositedAmount, note, createdAt, dealerAllocationId, doDate, allocationQty, id
  const defaultHeaders = [...ALLOC_SHEET_TABS.challans.headers];
  const withDefaultHeaders = parseChallanRowsFromTable([defaultHeaders, ...grid]);
  if (withDefaultHeaders.length > 0 && withDefaultHeaders.some((c) => c.challanNo || c.depositedAmount > 0)) {
    return withDefaultHeaders;
  }

  // Fallback smart inference per row when pasted columns are in a custom order
  const inferred: ChallanRecord[] = [];
  const seenIds = new Set<string>();
  grid.forEach((cells, idx) => {
    const nonEmpty = cells.map((c) => c.trim()).filter(Boolean);
    if (nonEmpty.length === 0) return;
    let dateVal = '';
    let categoryVal: AllocationCategory | '' = '';
    let typeVal: ChallanRecord['challanType'] = 'মূল চালান';
    const numericCells: number[] = [];
    const textCandidates: string[] = [];

    for (const cell of nonEmpty) {
      const parsedDate = parseDateStr(cell);
      if (!dateVal && /^\d{4}-\d{2}-\d{2}$/.test(parsedDate)) {
        dateVal = parsedDate;
        continue;
      }
      if (cell.includes('আয়কর') || cell.toLowerCase().includes('tax')) {
        typeVal = 'আয়কর চালান';
        continue;
      }
      if (cell.includes('মূল চালান')) {
        typeVal = 'মূল চালান';
        continue;
      }
      const catGuess = normalizeCategoryName(cell);
      if (!categoryVal && (cell.includes('খাদ্য') || cell.includes('ওএমএস') || cell.includes('ইপি') || cell.includes('ভিজিএফ') || cell.includes('কাবিখা') || cell.includes('জি আর') || cell.includes('ভিডাব্লিউ'))) {
        categoryVal = catGuess;
        continue;
      }
      const cleanedNum = Number(bnToEnDigits(cell).replace(/[,৳\s]/g, ''));
      if (/^[\d০-৯.,]+$/.test(cell.replace(/[,৳\s]/g, '')) && Number.isFinite(cleanedNum)) {
        numericCells.push(cleanedNum);
      } else {
        textCandidates.push(cell);
      }
    }

    const challanNo =
      textCandidates.find((t) => /[\d০-৯]/.test(t) && t.length <= 24) ||
      (numericCells.length > 0 && Number.isInteger(numericCells[0]) && numericCells[0] > 0 && numericCells[0] < 100000000 && numericCells.length > 1
        ? String(numericCells.shift()!)
        : '');
    const dealerName = textCandidates.find((t) => t !== challanNo) || '';
    const amountNums = numericCells.filter((n) => n >= 100);
    const depositedAmount = amountNums.length > 0 ? round2(amountNums[amountNums.length - 1]) : 0;
    const recordedAmount = amountNums.length > 1 ? round2(amountNums[0]) : depositedAmount;

    if (!normChallanNo(challanNo) && depositedAmount <= 0) return;

    inferred.push({
      id: makeDeterministicChallanId(
        'ch-paste',
        typeVal,
        challanNo,
        dateVal,
        dealerName,
        categoryVal || 'খাদ্য বান্ধব',
        idx,
        seenIds
      ),
      challanNo,
      challanDate: dateVal,
      category: categoryVal || 'খাদ্য বান্ধব',
      dealerName,
      challanType: typeVal,
      bankName: '',
      doNo: '',
      recordedAmount,
      depositedAmount,
      note: 'পেস্ট থেকে পুনরুদ্ধার',
      createdAt: dateVal ? `${dateVal}T00:00:00.000Z` : '2025-01-01T00:00:00.000Z',
    });
  });

  return deduplicateChallanRecords(inferred);
}

export function parseChallanRowsFromTable(rows: unknown[][], workbookPreferMdy = false): ChallanRecord[] {
  const challanRows = mapRowsByHeader(rows);
  const preferMdy = detectPreferMdy(rows) || workbookPreferMdy;
  const out: ChallanRecord[] = [];
  const seenIds = new Set<string>();

  challanRows.forEach((r, i) => {
    const note = pickField(r, ['Note', 'note', 'remarks', 'comment', 'মন্তব্য']);
    const rawDealerName = pickField(r, [
      'Dealer_Name', 'dealerName', 'dealer', 'Dealer',
      'Recipient_Name', 'recipientName', 'recipient', 'partyName', 'party', 'name',
      'ডিলার', 'ডিলারের নাম', 'প্রাপক', 'প্রাপকের নাম', 'প্রতিষ্ঠান', 'নাম',
    ]);
    const commentPartyMatch = note.match(/প্রদানকারী\s*[:ঃ]\s*([^|\n]+)/);
    const dealerName = rawDealerName || (commentPartyMatch ? commentPartyMatch[1].trim() : '');
    const dealerAllocationId = pickField(r, [
      'dealerAllocationId', 'dealer_allocation_id', 'suballocationId', 'allocationId',
    ]);
    const baseCategory = normalizeCategoryName(
      pickField(r, CATEGORY_FIELD_KEYS),
      `${dealerName} ${note}`
    );
    const bankName = pickField(r, ['Bank_Name', 'bankName', 'bank', 'Bank', 'branch', 'ব্যাংক', 'ব্যাংকের নাম', 'ব্যাংক ও শাখা']);
    const doNo = pickField(r, ['DO_No', 'doNo', 'doNumber', 'ডিও নং', 'ডিও নম্বর', 'ডিও']);
    const doDate = parseDateStr(
      pickField(r, ['DO_Date', 'doDate', 'ডিও তারিখ']),
      preferMdy
    ) || undefined;

    const mainNo = pickField(r, [
      'Challan_No', 'challanNo', 'Challan Number', 'ChallanNumber', 'Challan',
      'Main_Challan_No', 'mainChallanNo', 'trxId', 'voucherNo',
      'চালান নং', 'চালান নম্বর', 'চালান', 'মূল চালান নং', 'মূল চালান', 'ট্রেজারি চালান নং',
    ]);
    const taxNoExplicit = pickField(r, [
      'Tax_Challan_No', 'taxChallanNo', 'IncomeTaxChallanNo', 'incomeTaxChallanNo',
      'আয়কর চালান নং', 'আয়কর চালান', 'ভ্যাট/আয়কর চালান', 'ট্যাক্স চালান',
    ]);

    const mainDate = parseDateStr(
      pickField(r, ['Challan_Date', 'challanDate', 'mainChallanDate', 'date', 'Date', 'entryDate', 'timestamp', 'তারিখ', 'চালানের তারিখ', 'জমার তারিখ']),
      preferMdy
    );
    const taxDate =
      parseDateStr(
        pickField(r, [
          'Tax_Challan_Date', 'taxChallanDate', 'IncomeTaxDate', 'incomeTaxDate', 'income_tax_date',
          'আয়কর তারিখ', 'আয়কর চালানের তারিখ',
        ]),
        preferMdy
      ) || mainDate;

    const rawCreatedAt = pickField(r, ['Created_At', 'createdAt', 'timestamp']);
    const stableCreatedAt = rawCreatedAt || (mainDate ? `${mainDate}T00:00:00.000Z` : '2025-01-01T00:00:00.000Z');

    const rawType = pickField(r, ['Challan_Type', 'challanType', 'type', 'Type', 'kind', 'ধরন', 'চালানের ধরন']);
    const rate = pickNum(r, ['rate', 'unitPrice', 'দর']);
    const qty = pickNum(r, ['quantity', 'qty', 'allocationQty', 'পরিমাণ']);
    const recMainRaw = pickNum(r, [
      'Recorded_Amount', 'recordedAmount', 'requiredAmount', 'payableAmount', 'targetAmount',
      'রেকর্ড অনুযায়ী টাকা', 'রেকর্ড টাকা', 'রেকর্ড', 'ধার্যকৃত টাকা', 'প্রদেয় টাকা',
    ]);
    const recMain = recMainRaw > 0 ? recMainRaw : rate > 0 && qty > 0 ? round2(rate * qty) : 0;

    const depMain = pickNum(r, [
      'Deposited_Amount', 'depositedAmount', 'paidAmount', 'depositAmount', 'challanAmount',
      'amount', 'Amount', 'totalAmount', 'মূল চালান টাকা', 'জমাকৃত টাকা', 'জমার পরিমাণ', 'জমা', 'মোট টাকা', 'টাকা',
    ]);

    const recTax = pickNum(r, ['Required_Tax_Amount', 'requiredTaxAmount', 'recordedTaxAmount', 'রেকর্ড আয়কর']);
    const depTax = pickNum(r, [
      'Tax_Challan_Amount', 'taxChallanAmount', 'IncomeTaxAmount', 'incomeTaxAmount', 'income_tax_amount',
      'taxAmount', 'depositedTaxAmount', 'আয়কর টাকা', 'আয়করের পরিমাণ',
    ]);

    const parsedQty = qty > 0 ? round3(qty) : undefined;
    const rawRowId = pickField(r, ['ID', 'id']);

    // Case A: Row has BOTH explicit main + tax challan columns -> parse cleanly into paired records referencing same sourceRowId
    if ((taxNoExplicit || depTax > 0) && (mainNo || depMain > 0)) {
      if (mainNo || dealerName || dealerAllocationId) {
        const mId = rawRowId
          ? makeUniqueId(rawRowId, 'ch-ext-m', i, seenIds)
          : makeDeterministicChallanId('ch-ext-m', 'মূল চালান', mainNo, mainDate, dealerName, baseCategory, i, seenIds);
        out.push({
          id: mId,
          sourceRowId: rawRowId || undefined,
          challanNo: mainNo,
          challanDate: mainDate,
          category: baseCategory,
          dealerName,
          dealerAllocationId: dealerAllocationId || undefined,
          challanType: 'মূল চালান',
          bankName,
          doNo,
          doDate,
          allocationQty: parsedQty,
          recordedAmount: recMain,
          depositedAmount: depMain,
          note,
          createdAt: stableCreatedAt,
        });
      }
      const sameAsMainNo =
        Boolean(mainNo) && Boolean(taxNoExplicit) && normChallanNo(taxNoExplicit) === normChallanNo(mainNo);
      if (taxNoExplicit && (!sameAsMainNo || depTax > 0)) {
        const tId = makeDeterministicChallanId(
          'ch-ext-t',
          'আয়কর চালান',
          taxNoExplicit,
          taxDate,
          dealerName,
          baseCategory,
          i,
          seenIds
        );
        out.push({
          id: tId,
          sourceRowId: rawRowId || undefined,
          challanNo: taxNoExplicit,
          challanDate: taxDate,
          category: baseCategory,
          dealerName,
          dealerAllocationId: dealerAllocationId || undefined,
          challanType: 'আয়কর চালান',
          bankName,
          doNo,
          doDate,
          allocationQty: parsedQty,
          recordedAmount: recTax,
          depositedAmount: depTax,
          note,
          createdAt: stableCreatedAt,
        });
      }
      return;
    }

    // Case B: Single challan per row
    const finalNo = mainNo || taxNoExplicit;
    if (!finalNo && !dealerName && !dealerAllocationId) return;
    if (!finalNo && depMain <= 0 && depTax <= 0 && recMain <= 0 && recTax <= 0) return;
    if (!finalNo && /^(মোট|সর্বমোট|total|grand\s*total)$/i.test(dealerName.trim())) return;
    const isTax =
      rawType.includes('আয়কর') ||
      rawType.toLowerCase().includes('tax') ||
      rawType.toLowerCase().includes('vat') ||
      (!mainNo && (Boolean(taxNoExplicit) || depTax > 0));

    const cType: ChallanRecord['challanType'] = isTax ? 'আয়কর চালান' : 'মূল চালান';
    const cDate = isTax ? taxDate : mainDate;
    const cId = rawRowId
      ? makeUniqueId(rawRowId, 'ch-ext', i, seenIds)
      : makeDeterministicChallanId('ch-ext', cType, finalNo, cDate, dealerName, baseCategory, i, seenIds);

    out.push({
      id: cId,
      sourceRowId: rawRowId || undefined,
      challanNo: finalNo,
      challanDate: cDate,
      category: baseCategory,
      dealerName,
      dealerAllocationId: dealerAllocationId || undefined,
      challanType: cType,
      bankName,
      doNo,
      doDate,
      allocationQty: parsedQty,
      recordedAmount: isTax ? recTax || recMain : recMain,
      depositedAmount: isTax ? depTax || depMain : depMain,
      note,
      createdAt: stableCreatedAt,
    });
  });

  return deduplicateChallanRecords(out);
}

export async function fetchExternalChallansFromSheet(
  rawSpreadsheetId: string,
  accessToken?: string | null
): Promise<{ challans: ChallanRecord[]; title: string; tabUsed?: string }> {
  const spreadsheetId = extractSpreadsheetId(rawSpreadsheetId);
  if (!spreadsheetId) throw new Error('চালান Google Sheet ID বা লিংক দিন।');

  if (accessToken) {
    const meta = await getSpreadsheetMetadata(accessToken, spreadsheetId);
    const primaryMatch = findMatchingSheetTitle(
      meta.sheetTitles,
      ALLOC_SHEET_TABS.challans.name,
      ALLOC_SHEET_TABS.challans.aliases
    );
    const candidates = primaryMatch
      ? [primaryMatch, ...meta.sheetTitles.filter((t) => t !== primaryMatch)]
      : meta.sheetTitles;

    for (const tab of candidates.slice(0, 6)) {
      const escaped = tab.replace(/'/g, "''");
      const resp = await googleFetch<{ valueRanges?: Array<{ values?: unknown[][] }> }>(
        `${SHEETS_API_BASE}/${encodeURIComponent(spreadsheetId)}/values:batchGet?ranges=${encodeURIComponent(`'${escaped}'!A1:ZZ`)}&majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE`,
        accessToken
      );
      const parsed = parseChallanRowsFromTable(resp.valueRanges?.[0]?.values || []);
      if (parsed.length > 0) {
        return { challans: parsed, title: meta.title, tabUsed: tab };
      }
    }
    return { challans: [], title: meta.title };
  }

  const { meta, gidMap } = await getPublicSpreadsheetMetadata(spreadsheetId);
  const primaryMatch = findMatchingSheetTitle(
    meta.sheetTitles,
    ALLOC_SHEET_TABS.challans.name,
    ALLOC_SHEET_TABS.challans.aliases
  );
  const candidates =
    meta.sheetTitles.length > 0
      ? primaryMatch
        ? [primaryMatch, ...meta.sheetTitles.filter((t) => t !== primaryMatch)]
        : meta.sheetTitles
      : [ALLOC_SHEET_TABS.challans.name, 'Challan', 'Sheet1', 'Form Responses 1'];

  for (const tab of candidates.slice(0, 6)) {
    const rows = await fetchPublicCsvSheet(spreadsheetId, gidMap[tab], tab);
    const parsed = parseChallanRowsFromTable(rows);
    if (parsed.length > 0) {
      return { challans: parsed, title: meta.title, tabUsed: tab };
    }
  }
  return { challans: [], title: meta.title };
}

export async function fetchExternalChallansFromAppsScript(
  rawUrl: string
): Promise<{ challans: ChallanRecord[]; sourceUrl: string }> {
  const url = rawUrl.trim();
  if (!url) throw new Error('চালান ওয়েব অ্যাপ URL দিন।');

  const isNativeOrLocal =
    typeof window !== 'undefined' &&
    window.location.protocol === 'file:';

  let json: unknown = null;
  if (!isNativeOrLocal) {
    const resp = await fetch('/api/gas-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url, action: 'getAppData' }),
    });
    const body = (await resp.json()) as { ok?: boolean; data?: unknown; error?: string };
    if (!body?.ok) {
      throw new Error(body?.error || 'চালান Apps Script থেকে ডেটা পাওয়া যায়নি।');
    }
    json = body.data;
  } else {
    const u = new URL(url);
    u.searchParams.set('api', '1');
    u.searchParams.set('action', 'getAppData');
    const resp = await fetch(u.toString());
    json = await resp.json();
  }

  const root = (json && typeof json === 'object' ? json : {}) as Record<string, unknown>;
  const rawList = Array.isArray(json)
    ? json
    : Array.isArray(root.challans)
      ? root.challans
      : Array.isArray(root.data)
        ? root.data
        : Array.isArray(root.rows)
          ? root.rows
          : [];

  if (rawList.length === 0) {
    return { challans: [], sourceUrl: url };
  }

  let table: unknown[][];
  if (Array.isArray(rawList[0])) {
    table = rawList as unknown[][];
  } else {
    const firstObj = rawList[0] as Record<string, unknown>;
    const headers = Object.keys(firstObj);
    table = [
      headers,
      ...rawList.map((item) => {
        const obj = (item || {}) as Record<string, unknown>;
        return headers.map((h) => obj[h] ?? '');
      }),
    ];
  }

  return {
    challans: parseChallanRowsFromTable(table),
    sourceUrl: url,
  };
}

export async function fetchAllocationFromOAuthSheet(
  accessToken: string,
  rawSpreadsheetId: string,
  currentDb?: AllocationDatabase
): Promise<{ db: AllocationDatabase; title: string; tabsFound: string[]; matchedTabNames: string[] }> {
  const spreadsheetId = extractSpreadsheetId(rawSpreadsheetId);
  if (!spreadsheetId) throw new Error('Google Sheet ID বা লিংক দিন।');

  const meta = await getSpreadsheetMetadata(accessToken, spreadsheetId);
  const entries: Array<[AllocationRawTabKey, { name: string; aliases: readonly string[] }]> = [
    ...(Object.entries(ALLOC_SHEET_TABS) as Array<
      [keyof typeof ALLOC_SHEET_TABS, (typeof ALLOC_SHEET_TABS)[keyof typeof ALLOC_SHEET_TABS]]
    >),
    ['legacyProjects', LEGACY_COMBINED_PROJECTS_TAB],
  ];

  const matchedCandidatesMap = new Map<AllocationRawTabKey, string[]>();
  const matchedTabs = new Set<AllocationRawTabKey>();
  const matchedTabNames: string[] = [];
  const ranges: string[] = [];
  const rangeRefs: Array<{ key: AllocationRawTabKey; title: string }> = [];
  for (const [key, def] of entries) {
    const candidates = findAllMatchingSheetTitlesForWrite(
      meta.sheetTitles,
      def.name,
      def.aliases,
      !isExactOnlyTabKey(key),
      key
    );
    if (candidates.length > 0) {
      matchedCandidatesMap.set(key, candidates);
      matchedTabs.add(key);
      matchedTabNames.push(candidates[0]);
      for (const cand of candidates.slice(0, 2)) {
        const escaped = cand.replace(/'/g, "''");
        ranges.push(`'${escaped}'!A1:ZZ`);
        rangeRefs.push({ key, title: cand });
      }
    }
  }

  if (matchedTabs.size === 0 && meta.sheetTitles.length > 0) {
    throw new Error(
      `"${meta.title}" শিটে বরাদ্দ/ডিও-এর কাঙ্ক্ষিত ট্যাব পাওয়া যায়নি (পাওয়া ট্যাব: ${meta.sheetTitles.slice(0, 6).join(', ')}).`
    );
  }

  const rawTables: Partial<Record<AllocationRawTabKey, unknown[][]>> = {};
  if (ranges.length > 0) {
    const params = new URLSearchParams();
    ranges.forEach((r) => params.append('ranges', r));
    params.set('majorDimension', 'ROWS');
    params.set('valueRenderOption', 'UNFORMATTED_VALUE');
    const resp = await googleFetch<{ valueRanges?: Array<{ values?: unknown[][] }> }>(
      `${SHEETS_API_BASE}/${encodeURIComponent(spreadsheetId)}/values:batchGet?${params.toString()}`,
      accessToken
    );
    const byKey = new Map<AllocationRawTabKey, Array<{ title: string; values: unknown[][] }>>();
    (resp.valueRanges || []).forEach((vr, idx) => {
      const ref = rangeRefs[idx];
      if (!ref) return;
      const list = byKey.get(ref.key) || [];
      list.push({ title: ref.title, values: vr.values || [] });
      byKey.set(ref.key, list);
    });
    for (const [key, list] of byKey.entries()) {
      const primaryEntry = list[0];
      if (!primaryEntry) continue;
      if (primaryEntry.values.length <= 1 && list.length > 1 && list[1].values.length > 1) {
        rawTables[key] = list[1].values;
        const idx = matchedTabNames.indexOf(primaryEntry.title);
        if (idx >= 0) matchedTabNames[idx] = list[1].title;
      } else {
        rawTables[key] = primaryEntry.values;
      }
    }
  }

  return {
    db: buildAllocationDbFromRawTables(rawTables, matchedTabs, currentDb),
    title: meta.title,
    tabsFound: meta.sheetTitles,
    matchedTabNames,
  };
}

export async function autoDetectAllocationSpreadsheets(accessToken: string): Promise<{
  files: DriveSpreadsheetFile[];
  main?: { file: DriveSpreadsheetFile; meta: SpreadsheetMetadata };
  challan?: { file: DriveSpreadsheetFile; meta: SpreadsheetMetadata };
}> {
  const files = await listUserSpreadsheets(accessToken);
  let main: { file: DriveSpreadsheetFile; meta: SpreadsheetMetadata } | undefined;
  let challan: { file: DriveSpreadsheetFile; meta: SpreadsheetMetadata } | undefined;

  const sample = files.slice(0, 15);
  for (let i = 0; i < sample.length; i += 5) {
    const chunk = sample.slice(i, i + 5);
    const metas = await Promise.all(
      chunk.map(async (file) => {
        try {
          const meta = await getSpreadsheetMetadata(accessToken, file.id);
          return { file, meta };
        } catch {
          return null;
        }
      })
    );
    for (const item of metas) {
      if (!item) continue;
      const titles = item.meta.sheetTitles;
      const hasMin = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.ministry.name, ALLOC_SHEET_TABS.ministry.aliases));
      const hasSub = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.dealerSub.name, ALLOC_SHEET_TABS.dealerSub.aliases));
      const hasDo = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.doIssue.name, ALLOC_SHEET_TABS.doIssue.aliases));
      const hasChallan = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.challans.name, ALLOC_SHEET_TABS.challans.aliases));
      const looksChallanOnly = hasChallan && !hasMin && !hasSub && !hasDo;

      if (!main && (hasMin || hasSub || hasDo)) {
        main = item;
      }
      if (!challan && (looksChallanOnly || (hasChallan && item.file.id !== main?.file.id))) {
        challan = item;
      }
    }
    if (main && challan) break;
  }

  return { files, main, challan };
}

