const GITHUB_API_BASE = 'https://api.github.com';

export function utf8ToBase64(text: string): string {
  const bytes = new TextEncoder().encode(text);
  return uint8ArrayToBase64(bytes);
}

export function uint8ArrayToBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(bytes).toString('base64');
  }
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, i + chunkSize);
    binary += String.fromCharCode(...chunk);
  }
  return btoa(binary);
}

export function parseGitHubRepositoryInput(rawInput: string): { owner: string; repo: string } {
  const cleaned = rawInput
    .trim()
    .replace(/^https?:\/\/(www\.)?github\.com\//i, '')
    .replace(/^git@github\.com:/i, '')
    .replace(/\.git$/i, '')
    .replace(/^\/+|\/+$/g, '');

  if (!cleaned) {
    throw new Error('GitHub রিপোজিটরির নাম বা লিংক দিন (যেমন: khaddo-boraddo অথবা username/khaddo-boraddo)।');
  }

  const parts = cleaned.split('/').filter(Boolean);
  if (parts.length === 1) {
    return { owner: '', repo: parts[0] };
  }
  if (parts.length >= 2) {
    return { owner: parts[0], repo: parts[1] };
  }
  throw new Error('সঠিক GitHub রিপোজিটরির নাম দিন (যেমন: username/repo-name)।');
}

async function ghRequest<T>(
  token: string,
  path: string,
  init: RequestInit = {}
): Promise<{ status: number; data: T; headers: Headers }> {
  const res = await fetch(`${GITHUB_API_BASE}${path}`, {
    ...init,
    headers: {
      Accept: 'application/vnd.github+json',
      Authorization: `Bearer ${token}`,
      'X-GitHub-Api-Version': '2022-11-28',
      ...(init.body ? { 'Content-Type': 'application/json' } : {}),
      ...(init.headers || {}),
    },
  });

  const text = await res.text();
  let data: unknown = {};
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { message: text };
    }
  }

  return { status: res.status, data: data as T, headers: res.headers };
}

function formatGitHubErrorMessage(status: number, data: { message?: string } | undefined, fallback: string): string {
  const rawMsg = (data?.message || '').trim();
  const lower = rawMsg.toLowerCase();

  if (status === 401 || lower.includes('bad credentials')) {
    return 'GitHub টোকেনটি সঠিক নয় অথবা মেয়াদ শেষ হয়েছে। নতুন টোকেন তৈরি করে পেস্ট করুন।';
  }
  if (lower.includes('workflow') && (lower.includes('scope') || lower.includes('permission') || status === 422 || status === 404)) {
    return 'টোকেনে "workflow" অনুমতি (scope) দেওয়া নেই! উপরের «১ ক্লিকে Token তৈরি করুন» বাটন দিয়ে repo এবং workflow দুটোই টিক দিয়ে নতুন টোকেন নিন।';
  }
  if (status === 403 && lower.includes('rate limit')) {
    return 'GitHub API রেট লিমিট পূর্ণ হয়েছে। কয়েক মিনিট পর আবার চেষ্টা করুন।';
  }
  if (status === 403) {
    return `GitHub অনুমতি প্রত্যাখ্যান করেছে: ${rawMsg || 'টোকেনে repo ও workflow scope আছে কিনা দেখুন।'}`;
  }
  return rawMsg ? `${fallback} (${rawMsg})` : fallback;
}

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function pushFilesToGitHub(options: GitHubPushOptions): Promise<GitHubPushResult> {
  const token = options.token.trim();
  if (!token) {
    throw new Error('GitHub Personal Access Token দিন।');
  }
  if (!Array.isArray(options.files) || options.files.length === 0) {
    throw new Error('আপলোড করার মতো কোনো সোর্স ফাইল পাওয়া যায়নি।');
  }

  const parsedRepo = parseGitHubRepositoryInput(options.repository);
  const autoCreateRepo = options.autoCreateRepo !== false;
  const isPrivateRepo = Boolean(options.isPrivateRepo);
  const commitMessage =
    options.commitMessage?.trim() || 'Update Khaddo Boraddo web & Android source code';

  // Deduplicate files cleanly by normalized path
  const fileMap = new Map<string, GitHubFileEntry>();
  for (const item of options.files) {
    const cleanPath = item.path.replace(/^\/+/, '').replace(/\/+/g, '/');
    if (!cleanPath || cleanPath.endsWith('/')) continue;
    fileMap.set(cleanPath, { path: cleanPath, base64Content: item.base64Content });
  }
  const files = Array.from(fileMap.values());
  const hasWorkflowFiles = files.some((f) => f.path.startsWith('.github/workflows/'));

  options.onProgress?.('GitHub অ্যাকাউন্ট যাচাই করা হচ্ছে...', 0, files.length);

  // 1. Verify authenticated user & scopes
  const userRes = await ghRequest<{ login?: string; message?: string }>(token, '/user');
  if (userRes.status >= 400 || !userRes.data?.login) {
    throw new Error(
      formatGitHubErrorMessage(userRes.status, userRes.data, 'GitHub অ্যাকাউন্ট যাচাই করা যায়নি')
    );
  }
  const authLogin = userRes.data.login;

  // Classic PATs expose X-OAuth-Scopes; Fine-grained PATs omit it
  const oauthScopesHeader = userRes.headers.get('x-oauth-scopes');
  if (oauthScopesHeader) {
    const scopes = oauthScopesHeader
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    if (!scopes.includes('repo') && !scopes.includes('public_repo')) {
      throw new Error(
        'টোকেনে "repo" অনুমতি নেই। উপরের «১ ক্লিকে Token তৈরি করুন» বাটনে ট্যাপ করে repo ও workflow টিক দিয়ে নতুন টোকেন তৈরি করুন।'
      );
    }
    if (hasWorkflowFiles && !scopes.includes('workflow')) {
      throw new Error(
        'টোকেনে "workflow" অনুমতি নেই (.github/workflows/build-apk.yml পুশ করতে workflow টিক দেওয়া আবশ্যক)। উপরের «১ ক্লিকে Token তৈরি করুন» লিংক ব্যবহার করুন।'
      );
    }
  }

  const owner = parsedRepo.owner || authLogin;
  const repo = parsedRepo.repo;

  // 2. Check if repository exists; create if requested
  options.onProgress?.(`রিপোজিটরি (${owner}/${repo}) পরীক্ষা করা হচ্ছে...`, 0, files.length);
  let createdRepo = false;
  let repoRes = await ghRequest<{
    name?: string;
    default_branch?: string;
    html_url?: string;
    message?: string;
  }>(token, `/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`);

  if (repoRes.status === 404) {
    if (!autoCreateRepo) {
      throw new Error(
        `GitHub-এ "${owner}/${repo}" রিপোজিটরি পাওয়া যায়নি। অটো-তৈরি অপশন চালু করুন অথবা আগে GitHub-এ রিপোজিটরি বানান।`
      );
    }
    if (owner.toLowerCase() !== authLogin.toLowerCase()) {
      throw new Error(
        `"${owner}/${repo}" রিপোজিটরি পাওয়া যায়নি এবং অন্য ইউজার/অর্গানাইজেশনের নামে অটো-তৈরি করা যাবে না।`
      );
    }

    options.onProgress?.(`নতুন রিপোজিটরি (${owner}/${repo}) তৈরি করা হচ্ছে...`, 0, files.length);
    const createRes = await ghRequest<{
      name?: string;
      default_branch?: string;
      html_url?: string;
      message?: string;
    }>(token, '/user/repos', {
      method: 'POST',
      body: JSON.stringify({
        name: repo,
        private: isPrivateRepo,
        auto_init: true,
        description: 'খাদ্যশস্য বরাদ্দ ও বিতরণ ব্যবস্থাপনা ওয়েব ও অ্যান্ড্রয়েড অ্যাপ',
      }),
    });
    if (createRes.status >= 400 || !createRes.data?.name) {
      throw new Error(
        formatGitHubErrorMessage(createRes.status, createRes.data, 'নতুন রিপোজিটরি তৈরি করা যায়নি')
      );
    }
    createdRepo = true;
    repoRes = createRes;
    await delay(1200);
  } else if (repoRes.status >= 400) {
    throw new Error(
      formatGitHubErrorMessage(repoRes.status, repoRes.data, 'রিপোজিটরি তথ্য পাওয়া যায়নি')
    );
  }

  const defaultBranch = repoRes.data?.default_branch || 'main';
  const targetBranch = options.branch?.trim() || defaultBranch || 'main';
  const repoPath = `/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;

  // 3. Resolve target branch head commit (and initialize if repo is completely empty)
  let refRes = await ghRequest<{ object?: { sha: string }; message?: string }>(
    token,
    `${repoPath}/git/ref/heads/${encodeURIComponent(targetBranch)}`
  );

  if (refRes.status === 409 || refRes.status === 404) {
    const branchesRes = await ghRequest<Array<{ name: string }>>(token, `${repoPath}/branches`);
    const branches = Array.isArray(branchesRes.data) ? branchesRes.data : [];

    if (branches.length === 0) {
      // Completely empty repo: seed initial commit via Contents API so Git Data API works
      options.onProgress?.('খালি রিপোজিটরি প্রস্তুত করা হচ্ছে...', 0, files.length);
      const seedRes = await ghRequest<{ message?: string }>(token, `${repoPath}/contents/README.md`, {
        method: 'PUT',
        body: JSON.stringify({
          message: 'Initialize repository',
          content: utf8ToBase64('# Khaddo Boraddo App\n'),
          branch: targetBranch,
        }),
      });
      if (seedRes.status >= 400) {
        throw new Error(
          formatGitHubErrorMessage(seedRes.status, seedRes.data, 'খালি রিপোজিটরি ইনিশিয়ালাইজ করা যায়নি')
        );
      }
      await delay(800);
      refRes = await ghRequest<{ object?: { sha: string }; message?: string }>(
        token,
        `${repoPath}/git/ref/heads/${encodeURIComponent(targetBranch)}`
      );
    } else if (refRes.status === 404) {
      // Target branch doesn't exist yet; fork from default branch
      const baseRefRes = await ghRequest<{ object?: { sha: string }; message?: string }>(
        token,
        `${repoPath}/git/ref/heads/${encodeURIComponent(branches[0].name)}`
      );
      if (baseRefRes.status >= 400 || !baseRefRes.data?.object?.sha) {
        throw new Error(
          formatGitHubErrorMessage(baseRefRes.status, baseRefRes.data, 'মূল ব্রাঞ্চ পাওয়া যায়নি')
        );
      }
      const createRefRes = await ghRequest<{ object?: { sha: string }; message?: string }>(
        token,
        `${repoPath}/git/refs`,
        {
          method: 'POST',
          body: JSON.stringify({
            ref: `refs/heads/${targetBranch}`,
            sha: baseRefRes.data.object.sha,
          }),
        }
      );
      if (createRefRes.status >= 400 || !createRefRes.data?.object?.sha) {
        throw new Error(
          formatGitHubErrorMessage(createRefRes.status, createRefRes.data, 'নতুন ব্রাঞ্চ তৈরি করা যায়নি')
        );
      }
      refRes = createRefRes;
    }
  }

  if (refRes.status >= 400 || !refRes.data?.object?.sha) {
    throw new Error(
      formatGitHubErrorMessage(refRes.status, refRes.data, `ব্রাঞ্চ (${targetBranch}) অ্যাক্সেস করা যায়নি`)
    );
  }

  const headCommitSha = refRes.data.object.sha;
  const headCommitRes = await ghRequest<{ tree?: { sha: string }; message?: string }>(
    token,
    `${repoPath}/git/commits/${headCommitSha}`
  );
  if (headCommitRes.status >= 400 || !headCommitRes.data?.tree?.sha) {
    throw new Error(
      formatGitHubErrorMessage(headCommitRes.status, headCommitRes.data, 'সর্বশেষ কমিট তথ্য পড়া যায়নি')
    );
  }
  const baseTreeSha = headCommitRes.data.tree.sha;

  // 4. Upload all file blobs in concurrent batches
  const uploadedBlobs: Array<{ path: string; sha: string }> = new Array(files.length);
  const CONCURRENCY = 8;
  let nextIdx = 0;
  let completedCount = 0;

  const uploadWorker = async () => {
    while (nextIdx < files.length) {
      const idx = nextIdx++;
      const file = files[idx];

      let lastErr: Error | null = null;
      for (let attempt = 0; attempt < 2; attempt++) {
        const blobRes = await ghRequest<{ sha?: string; message?: string }>(
          token,
          `${repoPath}/git/blobs`,
          {
            method: 'POST',
            body: JSON.stringify({
              content: file.base64Content,
              encoding: 'base64',
            }),
          }
        );
        if (blobRes.status < 400 && blobRes.data?.sha) {
          uploadedBlobs[idx] = { path: file.path, sha: blobRes.data.sha };
          lastErr = null;
          break;
        }
        lastErr = new Error(
          formatGitHubErrorMessage(blobRes.status, blobRes.data, `ফাইল আপলোড ব্যর্থ: ${file.path}`)
        );
        if (blobRes.status >= 500 || blobRes.status === 429) {
          await delay(500);
          continue;
        }
        break;
      }

      if (lastErr) throw lastErr;
      completedCount++;
      options.onProgress?.('ফাইল আপলোড হচ্ছে...', completedCount, files.length);
    }
  };

  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, files.length) }, () => uploadWorker()));

  // 5. Create Git Tree atomically
  options.onProgress?.('Git ট্রি ও কমিট তৈরি হচ্ছে...', files.length, files.length);
  const treePayload: {
    tree: Array<{ path: string; mode: '100644'; type: 'blob'; sha: string }>;
    base_tree?: string;
  } = {
    tree: uploadedBlobs.map((b) => ({
      path: b.path,
      mode: '100644',
      type: 'blob',
      sha: b.sha,
    })),
  };
  if (!options.cleanTree) {
    treePayload.base_tree = baseTreeSha;
  }

  const treeRes = await ghRequest<{ sha?: string; message?: string }>(token, `${repoPath}/git/trees`, {
    method: 'POST',
    body: JSON.stringify(treePayload),
  });
  if (treeRes.status >= 400 || !treeRes.data?.sha) {
    throw new Error(
      formatGitHubErrorMessage(treeRes.status, treeRes.data, 'Git ট্রি তৈরি করা যায়নি')
    );
  }

  // 6. Create Git Commit
  const commitRes = await ghRequest<{ sha?: string; html_url?: string; message?: string }>(
    token,
    `${repoPath}/git/commits`,
    {
      method: 'POST',
      body: JSON.stringify({
        message: commitMessage,
        tree: treeRes.data.sha,
        parents: [headCommitSha],
      }),
    }
  );
  if (commitRes.status >= 400 || !commitRes.data?.sha) {
    throw new Error(
      formatGitHubErrorMessage(commitRes.status, commitRes.data, 'Git কমিট তৈরি করা যায়নি')
    );
  }

  // 7. Update Branch Reference
  const updateRefRes = await ghRequest<{ message?: string }>(
    token,
    `${repoPath}/git/refs/heads/${encodeURIComponent(targetBranch)}`,
    {
      method: 'PATCH',
      body: JSON.stringify({
        sha: commitRes.data.sha,
        force: false,
      }),
    }
  );
  if (updateRefRes.status >= 400) {
    throw new Error(
      formatGitHubErrorMessage(updateRefRes.status, updateRefRes.data, 'ব্রাঞ্চ আপডেট করা যায়নি')
    );
  }

  const repoUrl = `https://github.com/${owner}/${repo}`;
  return {
    ok: true,
    owner,
    repo,
    branch: targetBranch,
    repoUrl,
    commitUrl: commitRes.data.html_url || `${repoUrl}/commit/${commitRes.data.sha}`,
    actionsUrl: `${repoUrl}/actions`,
    commitSha: commitRes.data.sha,
    filesUploaded: files.length,
    createdRepo,
  };
}

import { getApps, initializeApp, type FirebaseApp } from 'firebase/app';
import {
  getAuth,
  GoogleAuthProvider,
  onAuthStateChanged,
  signInWithPopup,
  type Auth,
  type User,
} from 'firebase/auth';
import firebaseConfig from '../../firebase-applet-config.json';
import { callAndroidNativeHttp } from './gasBridge';

export const GOOGLE_WORKSPACE_SCOPES = [
  'https://www.googleapis.com/auth/spreadsheets',
  'https://www.googleapis.com/auth/drive.metadata.readonly',
] as const;

export const GOOGLE_AUTH_PROJECT_ID = firebaseConfig.projectId || '';
export const LIVE_PWA_APP_URL =
  'https://ais-pre-v77c74ngmmljzsnq2hzggt-222504639342.asia-northeast1.run.app';
export const DEV_PWA_APP_URL =
  'https://ais-dev-v77c74ngmmljzsnq2hzggt-222504639342.asia-northeast1.run.app';

export function getApiBaseOrigin(): string {
  if (typeof window === 'undefined') return '';
  if (
    window.location.hostname === 'appassets.androidplatform.net' ||
    window.location.protocol === 'file:'
  ) {
    return LIVE_PWA_APP_URL;
  }
  return '';
}

let firebaseApp: FirebaseApp | null = null;
let firebaseAuth: Auth | null = null;

function ensureFirebaseAuth(): Auth {
  if (!firebaseApp) {
    firebaseApp = getApps().length > 0 ? getApps()[0] : initializeApp(firebaseConfig);
  }
  if (!firebaseAuth) {
    firebaseAuth = getAuth(firebaseApp);
  }
  return firebaseAuth;
}

function createGoogleProvider(): GoogleAuthProvider {
  const provider = new GoogleAuthProvider();
  for (const scope of GOOGLE_WORKSPACE_SCOPES) {
    provider.addScope(scope);
  }
  provider.setCustomParameters({
    prompt: 'select_account',
  });
  return provider;
}

let isSigningIn = false;
let cachedAccessToken: string | null = null;
let cachedAndroidUser: User | null = null;

interface AndroidBlobBridgeHandle {
  openExternalBrowser?: (targetUrl: string) => void;
}

function getAndroidBridge(): AndroidBlobBridgeHandle | undefined {
  if (typeof window === 'undefined') return undefined;
  return (window as unknown as { AndroidBlobBridge?: AndroidBlobBridgeHandle }).AndroidBlobBridge;
}

export function isAndroidWebViewOrigin(): boolean {
  if (typeof window === 'undefined') return false;
  if (window.location.hostname === 'appassets.androidplatform.net') return true;
  if (typeof getAndroidBridge() !== 'undefined') return true;
  const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
  return /; wv\)/i.test(ua);
}

export function hasOpenExternalBrowserBridge(): boolean {
  return typeof getAndroidBridge()?.openExternalBrowser === 'function';
}

export function openExternalBrowserIfAndroid(url: string): boolean {
  const bridge = getAndroidBridge();
  if (bridge?.openExternalBrowser) {
    bridge.openExternalBrowser(url);
    return true;
  }
  return false;
}

export function isInEmbeddedIframe(): boolean {
  if (typeof window === 'undefined') return false;
  try {
    return window.self !== window.top;
  } catch {
    return true;
  }
}

export function formatGoogleAuthError(err: unknown): string {
  const code =
    typeof err === 'object' && err !== null && 'code' in err
      ? String((err as { code?: unknown }).code || '')
      : '';
  const rawMessage = err instanceof Error ? err.message : String(err || '');
  const host = typeof window !== 'undefined' ? window.location.hostname : '';

  if (code === 'auth/unauthorized-domain' || rawMessage.includes('auth/unauthorized-domain')) {
    return `এই ওয়েবসাইটের ডোমেইন (${host || 'unknown'}) অনুমোদিত ডোমেইন তালিকায় যুক্ত নেই। Firebase Console (${GOOGLE_AUTH_PROJECT_ID}) → Authentication → Settings → Authorized domains-এ "${host}" যুক্ত করুন।`;
  }
  if (code === 'auth/popup-blocked' || rawMessage.includes('auth/popup-blocked')) {
    return 'ব্রাউজার লগইন পপআপ ব্লক করেছে। পপআপ অনুমতি দিন অথবা "নতুন ট্যাবে অ্যাপ খুলুন" লিংকে ক্লিক করে সরাসরি ব্রাউজারে সাইন-ইন করুন।';
  }
  if (
    code === 'auth/popup-closed-by-user' ||
    code === 'auth/cancelled-popup-request' ||
    rawMessage.includes('auth/popup-closed-by-user')
  ) {
    return 'গুগল লগইন সম্পন্ন হওয়ার আগেই পপআপ বন্ধ হয়েছে। অন্য শেয়ার করা জিমেইলে "Access blocked / Error 403" দেখালে Google Cloud Console-এর OAuth Test Users তালিকায় ওই ইমেইলটি যোগ করুন।';
  }
  if (code === 'auth/operation-not-allowed') {
    return `প্রোজেক্টে (${GOOGLE_AUTH_PROJECT_ID}) Google Sign-In চালু করা নেই।`;
  }
  if (code === 'auth/network-request-failed') {
    return 'ইন্টারনেট বা নেটওয়ার্ক সমস্যার কারণে গুগল সার্ভারে সংযোগ করা যায়নি।';
  }
  if (rawMessage) {
    return rawMessage;
  }
  return 'গুগল লগইন ব্যর্থ হয়েছে। অনুগ্রহ করে আবার চেষ্টা করুন।';
}

export const initGoogleAuth = (
  onAuthSuccess?: (user: User, token: string | null) => void,
  onAuthFailure?: () => void
) => {
  const auth = ensureFirebaseAuth();
  return onAuthStateChanged(auth, (user: User | null) => {
    if (user) {
      if (cachedAccessToken) {
        onAuthSuccess?.(user, cachedAccessToken);
      } else if (!isSigningIn) {
        cachedAccessToken = null;
        onAuthSuccess?.(user, null);
      }
    } else if (cachedAndroidUser && cachedAccessToken) {
      onAuthSuccess?.(cachedAndroidUser, cachedAccessToken);
    } else {
      cachedAccessToken = null;
      cachedAndroidUser = null;
      onAuthFailure?.();
    }
  });
};

function createRandomAuthState(): string {
  const bytes = new Uint8Array(18);
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    crypto.getRandomValues(bytes);
  } else {
    for (let i = 0; i < bytes.length; i++) {
      bytes[i] = Math.floor(Math.random() * 256);
    }
  }
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

interface AndroidAuthCallbackPayload {
  state?: string;
  accessToken?: string;
  email?: string;
  displayName?: string;
  uid?: string;
  photoUrl?: string;
}

export async function resolveReachablePwaOrigin(): Promise<string> {
  if (
    typeof window !== 'undefined' &&
    window.location.hostname !== 'appassets.androidplatform.net' &&
    window.location.origin.startsWith('https://')
  ) {
    return window.location.origin;
  }

  try {
    const liveProbe = await callAndroidNativeHttp(
      'GET',
      `${LIVE_PWA_APP_URL}/api/android-auth/consume?state=preflight-check`
    );
    if (liveProbe.ok && liveProbe.status === 200 && liveProbe.text.includes('"pending"')) {
      return LIVE_PWA_APP_URL;
    }
  } catch {
    // ignore
  }

  try {
    const devProbe = await callAndroidNativeHttp(
      'GET',
      `${DEV_PWA_APP_URL}/api/android-auth/consume?state=preflight-check`
    );
    if (devProbe.ok && devProbe.status === 200 && devProbe.text.includes('"pending"')) {
      return DEV_PWA_APP_URL;
    }
  } catch {
    // ignore
  }

  try {
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 5000);
    const probe = await fetch(
      `${LIVE_PWA_APP_URL}/api/android-auth/consume?state=preflight-check`,
      { signal: controller.signal }
    );
    window.clearTimeout(timer);
    const ct = probe.headers.get('content-type') || '';
    if (probe.ok && ct.includes('application/json')) {
      return LIVE_PWA_APP_URL;
    }
  } catch {
    // Ignore
  }

  throw new Error(
    `Google Sign-In ব্রিজ (${LIVE_PWA_APP_URL}) সংযোগ করা যায়নি। নিচের «৪. মূল শিট Save/Push Apps Script URL» ব্যবহার করলে গুগল লগইন ছাড়াই সব এন্ট্রি সরাসরি Google Sheet-এ সেভ হবে!`
  );
}

let activeAndroidAuthCancel: (() => void) | null = null;

export function cancelPendingAndroidSignIn(): void {
  if (activeAndroidAuthCancel) {
    activeAndroidAuthCancel();
    activeAndroidAuthCancel = null;
  }
  isSigningIn = false;
}

async function signInViaAndroidChromeBridge(): Promise<{ user: User; accessToken: string }> {
  if (!hasOpenExternalBrowserBridge()) {
    throw new Error(
      'আপনার ফোনে ইনস্টল করা পুরনো APK-তে Chrome-লগইন ব্রিজ নেই। নিচের «অ্যান্ড্রয়েড APK প্রজেক্ট (.zip)» ডাউনলোড করে নতুন APK ইনস্টল করুন।'
    );
  }

  const handoffOrigin = await resolveReachablePwaOrigin();
  const state = createRandomAuthState();
  const handoffUrl = `${handoffOrigin}/?android_auth=1&state=${encodeURIComponent(state)}`;

  if (!openExternalBrowserIfAndroid(handoffUrl)) {
    throw new Error('অ্যান্ড্রয়েড Chrome ব্রাউজার চালু করা যায়নি।');
  }

  return new Promise<{ user: User; accessToken: string }>((resolve, reject) => {
    let settled = false;
    let pollTimer: number | null = null;
    let timeoutTimer: number | null = null;
    let inFlight = false;

    const cleanup = () => {
      if (pollTimer !== null) window.clearInterval(pollTimer);
      if (timeoutTimer !== null) window.clearTimeout(timeoutTimer);
      document.removeEventListener('visibilitychange', onVisibility);
      delete (window as unknown as { __onAndroidAuthCallback?: unknown }).__onAndroidAuthCallback;
      activeAndroidAuthCancel = null;
    };

    activeAndroidAuthCancel = () => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error('গুগল লগইন বাতিল করা হয়েছে। চাইলে নিচের Apps Script URL দিয়ে লগইন ছাড়াই শিটে সেভ করতে পারবেন।'));
    };

    const completeWithAuth = (
      token: string,
      userInfo?: {
        uid?: string;
        email?: string | null;
        displayName?: string | null;
        photoURL?: string | null;
      }
    ) => {
      if (settled || !token) return;
      settled = true;
      cleanup();
      const profile = {
        uid: userInfo?.uid || `android-${state.slice(0, 8)}`,
        email: userInfo?.email || null,
        displayName: userInfo?.displayName || userInfo?.email || 'Google যুক্ত',
        photoURL: userInfo?.photoURL || null,
      } as unknown as User;
      cachedAccessToken = token;
      cachedAndroidUser = profile;
      resolve({ user: profile, accessToken: token });
    };

    const tryConsume = async () => {
      if (settled || inFlight) return;
      inFlight = true;
      const consumeUrl = `${handoffOrigin}/api/android-auth/consume?state=${encodeURIComponent(state)}`;
      try {
        let data: {
          ok?: boolean;
          pending?: boolean;
          accessToken?: string;
          user?: {
            uid?: string;
            email?: string | null;
            displayName?: string | null;
            photoURL?: string | null;
          };
        } | null = null;

        try {
          const nativeRes = await callAndroidNativeHttp('GET', consumeUrl);
          if (nativeRes.ok && nativeRes.text.trim().startsWith('{')) {
            data = JSON.parse(nativeRes.text);
          }
        } catch {
          const res = await fetch(consumeUrl);
          if (res.ok) {
            data = await res.json();
          }
        }

        if (data?.ok && !data.pending && data.accessToken) {
          completeWithAuth(data.accessToken, data.user);
        }
      } catch {
        // ignore
      } finally {
        inFlight = false;
      }
    };

    const onVisibility = () => {
      if (document.visibilityState === 'visible') {
        void tryConsume();
      }
    };

    (
      window as unknown as {
        __onAndroidAuthCallback?: (payload: string | AndroidAuthCallbackPayload) => void;
      }
    ).__onAndroidAuthCallback = (payload: string | AndroidAuthCallbackPayload) => {
      if (typeof payload === 'object' && payload !== null) {
        const returnedState = payload.state || '';
        if ((!returnedState || returnedState === state) && payload.accessToken) {
          completeWithAuth(payload.accessToken, {
            uid: payload.uid,
            email: payload.email || null,
            displayName: payload.displayName || null,
            photoURL: payload.photoUrl || null,
          });
          return;
        }
        if (!returnedState || returnedState === state) {
          void tryConsume();
        }
        return;
      }

      if (!payload || payload === state) {
        void tryConsume();
      }
    };

    document.addEventListener('visibilitychange', onVisibility);
    pollTimer = window.setInterval(() => {
      void tryConsume();
    }, 1500);

    timeoutTimer = window.setTimeout(() => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(
        new Error(
          'ব্রাউজার থেকে গুগল লগইনের সময়সীমা শেষ হয়েছে। নিচের «৪. মূল শিট Save/Push Apps Script URL» ব্যবহার করে লগইন ছাড়াই শিটে সেভ করতে পারবেন।'
        )
      );
    }, 75_000);
  });
}

export async function submitAndroidAuthHandoff(
  state: string,
  user: User,
  accessToken: string
): Promise<void> {
  const res = await fetch('/api/android-auth/complete', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      state,
      accessToken,
      user: {
        uid: user.uid,
        email: user.email,
        displayName: user.displayName,
        photoURL: user.photoURL,
      },
    }),
  });
  if (!res.ok) {
    throw new Error('অ্যান্ড্রয়েড অ্যাপে লগইন সেশন পাঠানো যায়নি।');
  }
}

export const googleSignIn = async (): Promise<{ user: User; accessToken: string }> => {
  if (isAndroidWebViewOrigin()) {
    isSigningIn = true;
    try {
      return await signInViaAndroidChromeBridge();
    } finally {
      isSigningIn = false;
    }
  }

  const auth = ensureFirebaseAuth();
  const provider = createGoogleProvider();
  try {
    isSigningIn = true;
    const result = await signInWithPopup(auth, provider);
    const credential = GoogleAuthProvider.credentialFromResult(result);
    if (!credential?.accessToken) {
      throw new Error(
        'গুগল অ্যাকাউন্ট থেকে Google Sheets অ্যাক্সেস টোকেন পাওয়া যায়নি। সাইন-ইনের সময় সকল অনুমতির টিক দিয়ে আবার চেষ্টা করুন।'
      );
    }
    cachedAccessToken = credential.accessToken;
    return { user: result.user, accessToken: cachedAccessToken };
  } catch (err) {
    throw new Error(formatGoogleAuthError(err));
  } finally {
    isSigningIn = false;
  }
};

